const listAgentRunnerBindings = `-- name: ListAgentRunnerBindings :many
SELECT
    b.id AS binding_id,
    b.workspace_id,
    b.agent_id,
    b.machine_id,
    b.bound_by,
    b.created_at AS bound_at,
    m.owner_id,
    m.name,
    m.os,
    m.arch,
    m.client_version,
    b.roots,
    m.last_seen_at,
    m.created_at AS machine_created_at
FROM agent_runner_binding b
JOIN runner_machine m ON m.id = b.machine_id
WHERE b.workspace_id = $1
  AND b.agent_id = $2
  AND b.revoked_at IS NULL
  AND m.revoked_at IS NULL
ORDER BY b.created_at DESC
`

type ListAgentRunnerBindingsParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	AgentID     pgtype.UUID `json:"agent_id"`
}

type ListAgentRunnerBindingsRow struct {
	BindingID        pgtype.UUID        `json:"binding_id"`
	WorkspaceID      pgtype.UUID        `json:"workspace_id"`
	AgentID          pgtype.UUID        `json:"agent_id"`
	MachineID        pgtype.UUID        `json:"machine_id"`
	BoundBy          pgtype.UUID        `json:"bound_by"`
	BoundAt          pgtype.Timestamptz `json:"bound_at"`
	OwnerID          pgtype.UUID        `json:"owner_id"`
	Name             string             `json:"name"`
	Os               string             `json:"os"`
	Arch             string             `json:"arch"`
	ClientVersion    string             `json:"client_version"`
	Roots            []byte             `json:"roots"`
	LastSeenAt       pgtype.Timestamptz `json:"last_seen_at"`
	MachineCreatedAt pgtype.Timestamptz `json:"machine_created_at"`
}

func (q *Queries) ListAgentRunnerBindings(ctx context.Context, arg ListAgentRunnerBindingsParams) ([]ListAgentRunnerBindingsRow, error) {
	rows, err := q.db.Query(ctx, listAgentRunnerBindings, arg.WorkspaceID, arg.AgentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAgentRunnerBindingsRow{}
	for rows.Next() {
		var i ListAgentRunnerBindingsRow
		if err := rows.Scan(
			&i.BindingID,
			&i.WorkspaceID,
			&i.AgentID,
			&i.MachineID,
			&i.BoundBy,
			&i.BoundAt,
			&i.OwnerID,
			&i.Name,
			&i.Os,
			&i.Arch,
			&i.ClientVersion,
			&i.Roots,
			&i.LastSeenAt,
			&i.MachineCreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

