const upsertRunnerMachine = `-- name: UpsertRunnerMachine :one
INSERT INTO runner_machine (
    owner_id, name, os, arch, public_key, client_version
) VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (owner_id, public_key) DO UPDATE
SET name = EXCLUDED.name,
    os = EXCLUDED.os,
    arch = EXCLUDED.arch,
    client_version = EXCLUDED.client_version,
    revoked_at = NULL,
    revoked_by = NULL,
    updated_at = now()
RETURNING id, owner_id, name, os, arch, public_key, client_version, last_seen_at, revoked_at, revoked_by, created_at, updated_at
`

type UpsertRunnerMachineParams struct {
	OwnerID       pgtype.UUID `json:"owner_id"`
	Name          string      `json:"name"`
	Os            string      `json:"os"`
	Arch          string      `json:"arch"`
	PublicKey     []byte      `json:"public_key"`
	ClientVersion string      `json:"client_version"`
}

func (q *Queries) UpsertRunnerMachine(ctx context.Context, arg UpsertRunnerMachineParams) (RunnerMachine, error) {
	row := q.db.QueryRow(ctx, upsertRunnerMachine,
		arg.OwnerID,
		arg.Name,
		arg.Os,
		arg.Arch,
		arg.PublicKey,
		arg.ClientVersion,
	)
	var i RunnerMachine
	err := row.Scan(
		&i.ID,
		&i.OwnerID,
		&i.Name,
		&i.Os,
		&i.Arch,
		&i.PublicKey,
		&i.ClientVersion,
		&i.LastSeenAt,
		&i.RevokedAt,
		&i.RevokedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
